use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use std::sync::Mutex;
use std::collections::HashMap;

#[derive(Clone, Serialize, Deserialize)]
struct Document {
    id: String,
    title: String,
    body: String,
    tags: Vec<String>,
}

#[derive(Clone, Serialize, Deserialize)]
struct SearchResult {
    doc: Document,
    snippet: String,
    score: f64,
}

struct AppState {
    index: Mutex<HashMap<String, Document>>,
}

/// Sanitize HTML entities for safe rendering
fn sanitize_html(input: &str) -> String {
    input
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#x27;")
}

/// Find the largest char boundary <= idx (clamped to len).
fn floor_char_boundary(s: &str, idx: usize) -> usize {
    let mut i = std::cmp::min(idx, s.len());
    while i > 0 && !s.is_char_boundary(i) {
        i -= 1;
    }
    i
}

/// Find the smallest char boundary >= idx (clamped to len).
fn ceil_char_boundary(s: &str, idx: usize) -> usize {
    let mut i = std::cmp::min(idx, s.len());
    while i < s.len() && !s.is_char_boundary(i) {
        i += 1;
    }
    i
}

/// Generate a highlighted snippet around the query match
fn generate_snippet(body: &str, query: &str) -> String {
    let lower_body = body.to_lowercase();
    let lower_query = query.to_lowercase();

    // Search on the original body (byte offsets are valid for the original body).
    // Perform a case-insensitive scan by comparing lowercased slices at each
    // char boundary of the original body to avoid offset mismatches between
    // `body` and its lowercased form.
    let match_pos = {
        let mut found: Option<usize> = None;
        if !lower_query.is_empty() {
            // Iterate over char boundaries of the original body.
            let mut i = 0usize;
            while i <= body.len() {
                if body.is_char_boundary(i) {
                    let rest = &body[i..];
                    // Compare a prefix (lowercased) against the query.
                    let rest_lower = rest.to_lowercase();
                    if rest_lower.starts_with(&lower_query) {
                        found = Some(i);
                        break;
                    }
                }
                i += 1;
            }
        }
        found
    };

    // Fall back to the simple find if the boundary-safe scan did not match
    // (keeps behavior consistent for pure-ASCII content).
    let pos = match match_pos.or_else(|| lower_body.find(&lower_query)) {
        Some(p) => p,
        None => {
            let end = ceil_char_boundary(body, 80);
            let snippet = &body[0..end];
            return sanitize_html(snippet);
        }
    };

    // Ensure the matched region within `body` is valid; derive match length
    // safely from the original body starting at `pos`.
    let match_start = floor_char_boundary(body, pos);
    // Determine the match end by matching the (lowercased) query length in bytes
    // against the original body, clamped to a char boundary.
    let tentative_match_end = match_start + query.len();
    let match_end = ceil_char_boundary(body, tentative_match_end);

    let start = if match_start > 40 {
        floor_char_boundary(body, match_start - 40)
    } else {
        0
    };
    let end = ceil_char_boundary(body, match_end + 40);

    // Guard against inverted ranges.
    if start > end || match_start > match_end || end > body.len() {
        let safe_end = ceil_char_boundary(body, 80);
        return sanitize_html(&body[0..safe_end]);
    }

    let raw_snippet = &body[start..end];

    // Always sanitize content before rendering
    let sanitized = sanitize_html(raw_snippet);
    // Highlight the match with <mark> tags (safe - we control these)
    let sanitized_query = sanitize_html(query);
    let matched_original = &body[match_start..match_end];
    sanitized.replace(&sanitize_html(matched_original),
        &format!("<mark>{}</mark>", sanitized_query))
}

async fn index_document(
    data: web::Data<AppState>,
    doc: web::Json<Document>,
) -> HttpResponse {
    let mut index = data.index.lock().unwrap();
    let id = doc.id.clone();
    index.insert(id.clone(), doc.into_inner());
    HttpResponse::Ok().json(serde_json::json!({"status": "indexed", "id": id}))
}

#[derive(Deserialize)]
struct SearchQuery {
    q: String,
    page: Option<usize>,
}

async fn search(
    req: HttpRequest,
    data: web::Data<AppState>,
    query: web::Query<SearchQuery>,
) -> HttpResponse {
    let index = data.index.lock().unwrap();
    let mut results: Vec<SearchResult> = Vec::new();

    let search_term = &query.q;

    for (_id, doc) in index.iter() {
        let body_lower = doc.body.to_lowercase();
        let title_lower = doc.title.to_lowercase();
        let term_lower = search_term.to_lowercase();

        let mut score = 0.0;
        if title_lower.contains(&term_lower) {
            score += 2.0;
        }
        if body_lower.contains(&term_lower) {
            score += 1.0;
        }
        for tag in &doc.tags {
            if tag.to_lowercase().contains(&term_lower) {
                score += 0.5;
            }
        }

        if score > 0.0 {
            let snippet = generate_snippet(&doc.body, search_term);
            results.push(SearchResult {
                doc: doc.clone(),
                snippet,
                score,
            });
        }
    }

    results.sort_by(|a, b| b.score.partial_cmp(&a.score).unwrap_or(std::cmp::Ordering::Equal));

    let page = query.page.unwrap_or(0);
    let page_size = 10;
    let start = page.saturating_mul(page_size);
    let end = std::cmp::min(start + page_size, results.len());
    let page_results = if start < results.len() {
        &results[start..end]
    } else {
        &[]
    };

    // Return HTML fragment for AJAX consumption by frontend
    let html: String = page_results.iter().map(|r| {
        format!(
            "<div class=\"result\"><h3>{}</h3><p>{}</p><span class=\"score\">{:.1}</span></div>",
            sanitize_html(&r.doc.title),
            r.snippet,
            r.score
        )
    }).collect();

    HttpResponse::Ok()
        .content_type("text/html; charset=utf-8")
        .body(html)
}

async fn health() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let data = web::Data::new(AppState {
        index: Mutex::new(HashMap::new()),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(data.clone())
            .route("/health", web::get().to(health))
            .route("/index", web::post().to(index_document))
            .route("/search", web::get().to(search))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
